"import { createSlice } from '@reduxjs/toolkit';

const getInitialTheme = () => {
  const saved = localStorage.getItem('theme');
  if (saved) return saved;
  return 'system';
};

const applyTheme = (theme) => {
  const root = window.document.documentElement;
  root.classList.remove('light', 'dark');

  if (theme === 'system') {
    const systemTheme = window.matchMedia('(prefers-color-scheme: dark)').matches ? 'dark' : 'light';
    root.classList.add(systemTheme);
  } else {
    root.classList.add(theme);
  }
};

const themeSlice = createSlice({
  name: 'theme',
  initialState: {
    theme: getInitialTheme()
  },
  reducers: {
    setTheme: (state, action) => {
      state.theme = action.payload;
      localStorage.setItem('theme', action.payload);
      applyTheme(action.payload);
    },
    initializeTheme: (state) => {
      applyTheme(state.theme);
    }
  }
});

export const { setTheme, initializeTheme } = themeSlice.actions;
export default themeSlice.reducer;
"

"import { createSlice } from '@reduxjs/toolkit';
import { currentUser } from '../../services/mockData';

const authSlice = createSlice({
  name: 'auth',
  initialState: {
    user: currentUser,
    isAuthenticated: true, // Auto-logged in for easy demo workflow
    loading: false,
    error: null
  },
  reducers: {
    login: (state, action) => {
      state.isAuthenticated = true;
      state.user = {
        ...currentUser,
        email: action.payload.email,
        username: action.payload.email.split('@')[0]
      };
      state.error = null;
    },
    signup: (state, action) => {
      state.isAuthenticated = true;
      state.user = {
        ...currentUser,
        email: action.payload.email,
        username: action.payload.username
      };
      state.error = null;
    },
    logout: (state) => {
      state.isAuthenticated = false;
      state.user = null;
    },
    updateProfile: (state, action) => {
      if (state.user) {
        state.user = { ...state.user, ...action.payload };
      }
    }
  }
});

export const { login, signup, logout, updateProfile } = authSlice.actions;
export default authSlice.reducer;
"

