export const protect = async (req, res, next) => {
  let token;

  // Read JWT from request cookies
  if (req.cookies && req.cookies.token) {
    token = req.cookies.token;
  }

  if (!token) {
    return res.status(401).json({ message: 'Not authorized, login session token is missing' });
  }

  try {
    const decoded = jwt.verify(token, process.env.JWT_SECRET || 'antigravity-jwt-secret-key-98124');
    req.user = { id: decoded.id };
    next();
  } catch (error) {
    res.status(401).json({ message: 'Not authorized, token validation expired' });
  }
};

export default protect;
"

"export const errorHandler = (err, req, res, next) => {
  const statusCode = res.statusCode === 200 ? 500 : res.statusCode;
  res.status(statusCode).json({
    message: err.message,
    stack: process.env.NODE_ENV === 'production' ? null : err.stack
  });
};

export default errorHandler;
"

