"import React, { useRef, useState } from 'react';

export default function StorySpotlight({ children, className = "" }) {
  const containerRef = useRef(null);
  const [coords, setCoords] = useState({ x: 0, y: 0 });
  const [opacity, setOpacity] = useState(0);

  const handleMouseMove = (e) => {
    if (!containerRef.current) return;
    const rect = containerRef.current.getBoundingClientRect();
    setCoords({
      x: e.clientX - rect.left,
      y: e.clientY - rect.top
    });
  };

  return (
    <div
      ref={containerRef}
      onMouseMove={handleMouseMove}
      onMouseEnter={() => setOpacity(1)}
      onMouseLeave={() => setOpacity(0)}
      className={`relative overflow-hidden ${className}`}
    >
      {/* Cursor spotlight overlay */}
      <div 
        className="absolute pointer-events-none transition-opacity duration-300 z-15 rounded-full"
        style={{
          width: '320px',
          height: '320px',
          background: 'radial-gradient(circle, rgba(188, 140, 255, 0.08) 0%, transparent 75%)',
          left: `${coords.x - 160}px`,
          top: `${coords.y - 160}px`,
          opacity: opacity
        }}
      />
      {children}
