"import mongoose from 'mongoose';

const repositorySchema = new mongoose.Schema(
  {
    repoId: {
      type: String,
      required: true,
      unique: true,
      index: true
    },
    ownerId: {
      type: String, // Synced user uid (Firebase/mock session unique UID)
      required: true,
      index: true
    },
    repoName: {
      type: String,
      required: true,
      trim: true
    },
    description: {
      type: String,
      default: ''
    },
    visibility: {
      type: String,
      enum: ['public', 'private'],
      default: 'public'
    },
    language: {
      type: String,
      default: 'JavaScript'
    },
    stars: {
      type: Number,
      default: 0
    },
    forks: {
      type: Number,
      default: 0
    },
    isPinned: {
      type: Boolean,
      default: false
    },
    isArchived: {
      type: Boolean,
      default: false
    }
  },
  {
    timestamps: true
  }
);

export const Repository = mongoose.model('Repository', repositorySchema);
export default Repository;
"

"import mongoose from 'mongoose';

const contributionSchema = new mongoose.Schema(
  {
    uid: {
      type: String,
      required: true,
      index: true
    },
    date: {
      type: String, // Standard Date String key: YYYY-MM-DD
      required: true
    },
    commitCount: {
      type: Number,
      default: 0
    }
  },
  {
    timestamps: true
  }
);

// Compound unique index prevents daily duplicate commit count nodes
contributionSchema.index({ uid: 1, date: 1 }, { unique: true });

export const Contribution = mongoose.model('Contribution', contributionSchema);
export default Contribution;
"

"import mongoose from 'mongoose';

const activitySchema = new mongoose.Schema(
  {
    uid: {
      type: String,
      required: true,
      index: true
    },
    activityType: {
      type: String, // e.g. 'commit', 'repo_created', 'starred', 'profile_update'
      required: true
    },
    repository: {
      type: String,
      default: ''
    },
    details: {
      type: String,
      default: ''
    }
  },
  {
    timestamps: true
  }
);

export const Activity = mongoose.model('Activity', activitySchema);
export default Activity;
"

