"import React, { useState } from 'react';
import { Activity } from 'lucide-react';

export default function ContributionGraph({ contributions = [] }) {
  const [hoveredDay, setHoveredDay] = useState(null);
  const [tooltipPos, setTooltipPos] = useState({ x: 0, y: 0 });

  const getColorClass = (count) => {
    if (count === 0) return 'bg-[#161b22] border border-[#30363d]/40';
    if (count <= 2) return 'bg-[#0e4429]';
    if (count <= 4) return 'bg-[#006d32]';
    if (count <= 8) return 'bg-[#26a641]';
    return 'bg-[#39d353]';
  };

  // Generate days array for past 365 days
  const today = new Date();
  const days = [];
  const start = new Date();
  start.setDate(today.getDate() - 364);

  // Align start to nearest Sunday
  const startDay = start.getDay();
  start.setDate(start.getDate() - startDay);

  const end = new Date(today);
  let current = new Date(start);

  while (current <= end) {
    const dateStr = current.toISOString().split('T')[0];
    const match = contributions.find((c) => c.date === dateStr);
    const count = match ? match.commitCount : 0;

    days.push({
      date: dateStr,
      count,
      colorClass: getColorClass(count)
    });
    current.setDate(current.getDate() + 1);
  }

  const handleMouseEnter = (day, e) => {
    const rect = e.target.getBoundingClientRect();
    setHoveredDay(day);
    setTooltipPos({
      x: rect.left + window.scrollX - 50,
      y: rect.top + window.scrollY - 38
    });
  };

  const totalContributions = contributions.reduce((acc, curr) => acc + curr.commitCount, 0);

  return (
    <div className="glass-panel p-5 rounded-2xl border border-[#30363d]/60 custom-shadow space-y-4 relative">
      <h3 className="font-bold text-sm tracking-tight flex items-center gap-1.5 text-white">
        <Activity size={16} className="text-github-dark-accent" />
        <span>{totalContributions} contributions in the last year</span>
      </h3>

      {/* Grid container with custom horizontal scroll */}

