"import express from 'express';
import User from '../models/User.js';
import Repository from '../models/Repository.js';
import Contribution from '../models/Contribution.js';
import Activity from '../models/Activity.js';
import protect from '../middleware/authMiddleware.js';

const router = express.Router();

const getTodayDateString = () => {
  return new Date().toISOString().split('T')[0];
};

// @desc    Get complete profile package
// @route   GET /api/profile/:username
// @access  Public
router.get('/:username', async (req, res) => {
  try {
    const { username } = req.params;

    const user = await User.findOne({ username });
    if (!user) {
      return res.status(404).json({ message: 'User not found' });
    }

    const repositories = await Repository.find({ ownerId: user.uid }).sort({ updatedAt: -1 });
    const contributions = await Contribution.find({ uid: user.uid });
    const activities = await Activity.find({ uid: user.uid }).sort({ createdAt: -1 }).limit(20);

    res.status(200).json({
      success: true,
      user,
      repositories,
      contributions,
      activities
    });
  } catch (error) {
    res.status(500).json({ message: `Profile Load Error: ${error.message}` });
  }
});

// @desc    Update user profile meta information
// @route   PUT /api/profile/update
// @access  Private
router.put('/update', protect, async (req, res) => {
  try {
    const user = await User.findById(req.user.id);
    if (!user) {
      return res.status(404).json({ message: 'User session not found' });
    }

    user.firstName = req.body.firstName || user.firstName;
    user.lastName = req.body.lastName || user.lastName;
    user.bio = req.body.bio !== undefined ? req.body.bio : user.bio;
    user.company = req.body.company !== undefined ? req.body.company : user.company;
    user.location = req.body.location !== undefined ? req.body.location : user.location;
    user.website = req.body.website !== undefined ? req.body.website : user.website;


