"import { createSlice } from '@reduxjs/toolkit';
import { initialRepositories } from '../../services/mockData';

const repoSlice = createSlice({
  name: 'repos',
  initialState: {
    repositories: initialRepositories, // fallback/initial repos
    activeRepoId: 'github-clone-react',
    activeBranch: 'main',
    currentPath: [], // Array of folder names representing navigation path
    selectedFile: null, // { name, content, path }
    searchQuery: '',
    searchFilter: 'all' // all, repositories, issues, users, prs
  },
  reducers: {
    setRepositories: (state, action) => {
      // Map MongoDB structure to match expected frontend keys if needed
      state.repositories = action.payload.map(repo => ({
        id: repo.repoId,
        repoId: repo.repoId,
        name: repo.repoName,
        description: repo.description,
        isPrivate: repo.visibility === 'private',
        visibility: repo.visibility,
        stars: repo.stars,
        forks: repo.forks,
        ownerId: repo.ownerId,
        updatedAt: repo.updatedAt,
        createdAt: repo.createdAt,
        language: repo.language,
