"import express from 'express';
import cors from 'cors';
import helmet from 'helmet';
import cookieParser from 'cookie-parser';
import { rateLimit } from 'express-rate-limit';
import dotenv from 'dotenv';
import connectDB from './config/db.js';
import authRoutes from './routes/authRoutes.js';
import profileRoutes from './routes/profileRoutes.js';
import errorHandler from './middleware/errorMiddleware.js';

// Load environment variables
dotenv.config();

const app = express();
const PORT = process.env.PORT || 5000;

// Security Middlewares
app.use(helmet());

// CORS configuration supporting cookies credentials
app.use(
  cors({
    origin: ['http://localhost:5173', 'http://127.0.0.1:5173'],
    credentials: true
  })
);

// Rate limiting (max 100 requests per 15 mins)
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000,
  max: 100,
  message: { message: 'Too many requests from this client, please retry in 15 minutes.' }
});
app.use(limiter);

// Parsers
app.use(express.json());
app.use(cookieParser());

// Base health check
app.get('/', (req, res) => {
  res.json({ message: 'GitHub Clone Backend Authentication API running.' });
});

// Sync Routes
app.use('/api/auth', authRoutes);
app.use('/api/profile', profileRoutes);

// Global Error Interceptor
app.use(errorHandler);

// Bootstrap: Establish MongoDB Connection BEFORE listening for routes (Phase 2 & 15)
const startServer = async () => {
  await connectDB();
  app.listen(PORT, () => {
    console.log(`Server listening on port ${PORT} in ${process.env.NODE_ENV || 'development'} mode.`);
  });
};

startServer();
"

"import mongoose from 'mongoose';

const repositorySchema = new mongoose.Schema(
  {
    repoId: {
      type: String,
      required: true,
      unique: true,
      index: true
    },
    ownerId: {
      type: String, // UID of user
      required: true,
      index: true
    },
    repoName: {
      type: String,
      required: true,
      trim: true
    },
    description: {
      type: String,
      default: ''
    },
    visibility: {
      type: String,
      enum: ['public', 'private'],
      default: 'public',
      index: true
    },
    language: {
      type: String,
      default: 'JavaScript'
    },
    stars: {
      type: Number,
      default: 0
    },
    forks: {
      type: Number,
      default: 0
    },
    watchers: {
      type: Number,
      default: 1
    },
    openIssues: {
      type: Number,
      default: 0
    },
    defaultBranch: {
      type: String,
      default: 'main'
    },
    topics: {
      type: [String],
      default: []
    },
    hasReadme: {
      type: Boolean,
      default: false
    },
    hasGitignore: {
      type: Boolean,
      default: false
    },
    license: {
      type: String,
      default: 'None'
    },
    isPinned: {
      type: Boolean,
      default: false
    },
    isArchived: {
      type: Boolean,
      default: false
    }
  },
  {
    timestamps: true
  }
);

export const Repository = mongoose.model('Repository', repositorySchema);
export default Repository;
"

