"import express from 'express';
import multer from 'multer';
import path from 'path';
import fs from 'fs';
import protect from '../middleware/authMiddleware.js';
import User from '../models/User.js';

const router = express.Router();

// Ensure uploads/avatars directory exists on disk
const avatarDir = path.join(process.cwd(), 'uploads', 'avatars');
if (!fs.existsSync(avatarDir)) {
  fs.mkdirSync(avatarDir, { recursive: true });
}

// Multer Storage Engine
const storage = multer.diskStorage({
  destination: (req, file, cb) => {
    cb(null, avatarDir);
  },
  filename: (req, file, cb) => {
    const ext = path.extname(file.originalname);
    const filename = `${req.user?.uid || 'user'}_${Date.now()}${ext}`;
    cb(null, filename);
  }
});

const upload = multer({
  storage,
  limits: { fileSize: 5 * 1024 * 1024 }, // 5MB limit
  fileFilter: (req, file, cb) => {
    const allowed = /jpeg|jpg|png|webp|gif/;
    const extName = allowed.test(path.extname(file.originalname).toLowerCase());
    const mimeType = allowed.test(file.mimetype);
    if (extName && mimeType) {
      cb(null, true);
    } else {
      cb(new Error('Only image files (jpg, png, webp, gif) are allowed.'));
    }
  }
});

// POST /api/profile/avatar - Upload Avatar File to Disk
router.post('/avatar', protect, upload.single('avatar'), async (req, res) => {
  try {
    if (!req.file) {
      return res.status(400).json({ message: 'No file uploaded.' });
    }

    const avatarUrl = `/uploads/avatars/${req.file.filename}`;
    const uid = req.user.uid || req.user.id || 'mock_uid_dev';

    // Update in MongoDB User document if connected
    if (User.db && User.db.readyState === 1) {
      await User.findOneAndUpdate({ uid }, { avatar: avatarUrl, photo: avatarUrl });
    }

    res.json({
      success: true,
      message: 'Avatar uploaded successfully!',
      avatarUrl
    });
  } catch (error) {
    res.status(500).json({ message: error.message || 'Avatar upload failed.' });
  }
});\
